DataGenerator = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=DataGenerator]");
        $("[name=tabs]", container).kendoTabStrip({ animation: { open: { effects: "fadeIn" } } });
        loadComponent($(".tab[name=masterdata]", container), "DataGeneratorMasterdata", async (c) => {
            await c.init(session.app, $(".tab[name=masterdata]", container));
        });
        loadComponent($(".tab[name=transactions]", container), "DataGeneratorTransactions", async (c) => {
            await c.init(session.app, $(".tab[name=transactions]", container));
        });
    }

}
